#include "tigersheets/financial_workflows.hpp"
#include "tigersheets/session.hpp"
#include <iostream>
#include <stdexcept>
#include <cmath>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Json address(int row){return {{"sheet","sheet-1"},{"row",row},{"col",1}};}
int main(){try{
 Json book={{"revision",0},{"sheets",Json::array({{{"id","sheet-1"},{"name","Model"},{"cells",Json::array({{{"row",1},{"col",1},{"input","10"}},{{"row",2},{"col",1},{"input","=A1*2"}}})}},{{"id","reports"},{"name","Reports"},{"cells",Json::array()}}})}};CalculationContext context;context.snapshot=book;context.generation=19;CalculationEngine engine;context.evaluator=[&](const Json& candidate){return engine.calculate(candidate);};
 const Json definition={{"version",1},{"id","base"},{"name","Base assumptions"},{"kind","assumption_set"},{"cells",Json::array({{{"sheet","sheet-1"},{"row",1},{"col",1},{"type","number"},{"value",12}}})}};
 const auto result=executeFinancialWorkflow(book,definition,"save",context);require(result.at("analysis").at("success")==true&&result.at("analysis").at("status")=="saved","saved workflow yields an explicit successful review result");require(result.at("operations").size()==1&&result.at("operations")[0].at("type")=="save_financial_definition","saving assumptions returns one typed operation for acceptance");require(book==context.snapshot&&book.at("sheets")[0].at("cells")[0].at("input")=="10","workflow preparation never applies assumptions to live source");require(result.at("revision")==0&&result.at("contextGeneration")==19,"financial workflow results bind their immutable source epoch");
 const auto applied=executeFinancialWorkflow(book,definition,"run",context);require(applied["analysis"]["success"]&&applied["operations"].size()==2&&applied["operations"][0]["type"]=="save_financial_definition"&&applied["operations"][1]["type"]=="apply_financial_scenario","running draft assumptions saves and applies them in one reviewable batch");
 const Json forecast={{"id","forecast"},{"name","Forecast"},{"kind","forecast"},{"periods",2},{"drivers",Json::array({{{"name","Revenue"},{"base",address(1)},{"growth",0.1}}})},{"output",{{"sheet","reports"},{"row1",1},{"col1",1}}}};const auto report=executeFinancialWorkflow(book,forecast,"run",context);require(report["analysis"]["success"]&&report["operations"].size()==1&&report["operations"][0]["type"]=="replace_financial_model","financial report runs return generated output and definition atomically");
 const Json goal={{"id","goal"},{"name","Target revenue"},{"kind","goal_seek"},{"specification",{{"changing",address(1)},{"output",address(2)},{"target",40}}}};const auto savedGoal=executeFinancialWorkflow(book,goal,"save",context);require(savedGoal["analysis"]["success"]&&savedGoal["definition"]["specification"].contains("start")&&savedGoal["operations"][0]["definition"]["specification"].contains("maxEvaluations"),"saved numerical models persist normalized explicit settings");const auto sought=executeFinancialWorkflow(book,goal,"run",context);require(sought["analysis"]["success"]&&sought["operations"].size()==2&&std::abs(sought["analysis"]["value"].get<double>()-20)<1e-6,"qualified Goal Seek runs return setup plus one changing constant");
 auto withSettings=book;withSettings["settings"]={{"locale","en-US"},{"iterationEnabled",false}};auto settingsContext=context;settingsContext.snapshot=withSettings;int evaluations=0;settingsContext.evaluator=[&](const Json&){++evaluations;throw std::runtime_error("settings must not calculate");return Json();};const Json settings={{"kind","iteration"},{"settings",{{"iterationEnabled",true},{"maxIterations",250},{"maxChange",1e-9}}}};const auto updated=executeFinancialWorkflow(withSettings,settings,"settings",settingsContext);require(updated["analysis"]["success"]&&updated["operations"].size()==1&&updated["operations"][0]["type"]=="set_metadata"&&updated["operations"][0]["value"]["locale"]=="en-US"&&evaluations==0,"iteration controls produce a merged settings preview without calculating");for(const auto& bad:Json::array({Json{{"iterationEnabled",1}},Json{{"maxIterations",1.5}},Json{{"maxIterations",0}},Json{{"maxIterations",100001}},Json{{"maxChange",-1}},Json{{"locale","fr"}}})){auto invalid=settings;invalid["settings"]=bad;const auto rejected=executeFinancialWorkflow(withSettings,invalid,"settings",settingsContext);require(!rejected["analysis"]["success"].get<bool>()&&rejected["operations"].empty(),"invalid iteration settings cannot publish operations");}
 auto exact=settings;exact["settings"]["maxChange"]=0;const auto zero=executeFinancialWorkflow(withSettings,exact,"settings",settingsContext);require(zero["analysis"]["success"],"zero iteration tolerance is a valid exact-convergence setting");
 auto savedBook=book;savedBook["financialModels"]=Json::array({definition});auto savedContext=context;savedContext.snapshot=savedBook;for(const auto& action:{"apply","delete"}){const auto selected=executeFinancialWorkflow(savedBook,{{"id","base"}},action,savedContext);require(selected["analysis"]["success"]&&selected["operations"].size()==1,"identity-only saved model actions resolve the committed definition");}
 const auto example=executeFinancialWorkflow(book,Json::object(),"example",context);require(example["analysis"]["success"]&&example["operations"].size()>20&&example["operations"][0]["type"]=="add_sheet"&&book==context.snapshot,"the circular financing example remains a source-preserving review batch");
 const auto cancelled=executeFinancialWorkflow(book,forecast,"run",context,[]{return true;});require(!cancelled["analysis"]["success"].get<bool>()&&cancelled["analysis"]["status"]=="cancelled"&&cancelled["operations"].empty(),"cancelled financial workflows never return mutations");auto stale=context;stale.generationIsCurrent=[](auto){return false;};const auto foreign=executeFinancialWorkflow(book,definition,"save",stale);require(!foreign["analysis"]["success"].get<bool>()&&foreign["analysis"]["status"]=="stale_context"&&foreign["operations"].empty(),"even save-only financial workflows refuse stale epochs");require(book==context.snapshot&&book["sheets"][0]["cells"][0]["input"]=="10","all financial workflow preparations preserve source model inputs");std::cout<<"financial workflow tests passed\n";
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
